<?php
declare(strict_types=1);
namespace EPejabat\Modules\EForms;
use EPejabat\Core\{Core,Database,Audit};
/** Declarative content importer; never executes code or SQL from a form archive. */
final class Packages {
 const FILES=['manifest.json','form.json','workflow.json','pdf-mapping.json','layout.json','original.pdf'];
 public static function ready(\PDO $p):bool {return (bool)Database::query($p,"SELECT 1 FROM database_migrations WHERE version='eforms:Phase2:211_form_packages.sql' AND status='applied'")->fetchColumn();}
 private static function keys(array $r,array $allowed):void {if(array_diff(array_keys($r),$allowed))throw new \InvalidArgumentException('Medan schema tidak disokong.');}
 private static function json(string $raw):array {$v=json_decode($raw,true,48,JSON_THROW_ON_ERROR);if(!is_array($v))throw new \InvalidArgumentException('JSON object diperlukan.');return $v;}
 public static function inspect(string $path):array {
  if(is_link($path)||!is_file($path)||filesize($path)>12582912||filesize($path)<30)throw new \InvalidArgumentException('ZIP maksimum 12 MB.');
  $z=new \ZipArchive();if($z->open($path)!==true)throw new \InvalidArgumentException('ZIP tidak sah.');
  try{if($z->numFiles!==count(self::FILES))throw new \InvalidArgumentException('Pakej mesti mempunyai tepat enam fail.');$raw=[];$total=0;
   for($i=0;$i<$z->numFiles;$i++){$s=$z->statIndex($i);$n=$s['name'];if(!in_array($n,self::FILES,true)||isset($raw[$n]))throw new \InvalidArgumentException('Laluan/fail tidak dibenarkan.');$z->getExternalAttributesIndex($i,$ops,$attr);$type=($attr>>16)&0170000;if($type!==0&&$type!==0100000)throw new \InvalidArgumentException('Symlink atau fail bukan regular ditolak.');if(($s['encryption_method']??0)!==0||!in_array($s['comp_method'],[0,8],true))throw new \InvalidArgumentException('ZIP encryption/compression tidak disokong.');$limit=$n==='original.pdf'?10485760:300000;if($s['size']>$limit||$s['size']<1||$s['size']/max(1,$s['comp_size'])>200)throw new \InvalidArgumentException('Saiz/nisbah ZIP tidak selamat.');$total+=$s['size'];if($total>12000000)throw new \InvalidArgumentException('Jumlah ZIP terlalu besar.');$bytes=$z->getFromIndex($i,$limit+1);if(!is_string($bytes)||strlen($bytes)!==$s['size'])throw new \InvalidArgumentException('Fail ZIP rosak.');$raw[$n]=$bytes;}
  }finally{$z->close();}
  $m=self::json($raw['manifest.json']);self::keys($m,['schema_version','form_id','title','description','revision','category','engine_min','capabilities','organisation_scope','files']);
  if(($m['schema_version']??'')!=='1.0'||($m['engine_min']??'')!=='eforms-packages/1.0'||!preg_match('/\A[a-z][a-z0-9._-]{2,99}\z/',(string)($m['form_id']??''))||!is_int($m['revision']??null)||$m['revision']<1||$m['revision']>100000)throw new \InvalidArgumentException('Versi/identiti pakej tidak disokong.');
  if(($m['organisation_scope']??null)!==['mode'=>'admin_select'])throw new \InvalidArgumentException('Scope mesti ditetapkan Admin tempatan.');
  $caps=$m['capabilities']??[];if(!is_array($caps)||array_diff($caps,['original_pdf','conditional_fields','repeatable_rows','profile_autofill','sequential_approval']))throw new \InvalidArgumentException('Capability tidak disokong.');
  if(!is_array($m['files']??null)||count($m['files'])!==5)throw new \InvalidArgumentException('Manifest fail tidak lengkap.');foreach(array_slice(self::FILES,1) as $n){if(!is_string($m['files'][$n]??null)||!preg_match('/\A[a-f0-9]{64}\z/',$m['files'][$n])||!hash_equals($m['files'][$n],hash('sha256',$raw[$n])))throw new \InvalidArgumentException('Hash fail tidak sepadan: '.$n);}
  $m['title']=Core::text($m['title']??'',190);$m['description']=Core::text($m['description']??'',2000,false);$m['category']=Core::text($m['category']??'',100,false);
  $form=self::json($raw['form.json']);self::keys($form,['fields','acknowledgement']);if(!is_array($form['fields']??null))throw new \InvalidArgumentException('Medan borang diperlukan.');foreach($form['fields'] as $f){if(!is_array($f))throw new \InvalidArgumentException('Definisi tidak sah.');self::keys($f,['key','label','type','options','condition','required','autofill','columns','max_rows','min','max','max_length','confidence','placeholder','help']);}
  $fields=Schema::definition($form['fields']);$ack=Core::text($form['acknowledgement']??'',1000);
  $flow=self::json($raw['workflow.json']);self::keys($flow,['steps','allow_self_approval','allow_return','allow_reject']);if(($flow['allow_self_approval']??null)!==false||($flow['allow_return']??null)!==true||($flow['allow_reject']??null)!==true||!is_array($flow['steps']??null)||!$flow['steps']||count($flow['steps'])>5)throw new \InvalidArgumentException('Polisi workflow tidak disokong.');foreach($flow['steps'] as &$s){if(!is_array($s))throw new \InvalidArgumentException('Langkah tidak sah.');self::keys($s,['kind','label']);if(!in_array($s['kind']??'',['review','approve'],true))throw new \InvalidArgumentException('Jenis workflow tidak sah.');$s['label']=Core::text($s['label']??'',100);}unset($s);if(end($flow['steps'])['kind']!=='approve')throw new \InvalidArgumentException('Langkah akhir mesti approval.');
  $layout=self::json($raw['layout.json']);self::keys($layout,['mode','effective_date']);if(($layout['mode']??'')!=='original_pdf')throw new \InvalidArgumentException('Layout asal PDF diperlukan.');
  $mapping=self::json($raw['pdf-mapping.json']);self::keys($mapping,['pages','maps']);$mapping['category']=$m['category'];$mapping['effective_date']=$layout['effective_date']??'';$mapping['review_confirmed']=false;$definition=Visual::definition($mapping,$fields);if(!$definition['pages'])throw new \InvalidArgumentException('Metadata halaman diperlukan.');foreach($definition['maps'] as &$map)$map['confirmed']=false;unset($map);
  if(!str_starts_with($raw['original.pdf'],'%PDF-')||(new \finfo(FILEINFO_MIME_TYPE))->buffer($raw['original.pdf'])!=='application/pdf')throw new \InvalidArgumentException('Original PDF tidak sah.');
  return ['manifest'=>$m,'fields'=>$fields,'acknowledgement'=>$ack,'steps'=>$flow['steps'],'definition'=>$definition,'pdf'=>$raw['original.pdf'],'sha256'=>hash_file('sha256',$path)];
 }
 private static function dir(string $name):string {$d=APP_ROOT.'/storage/'.$name;if(is_link(APP_ROOT.'/storage')||is_link($d))throw new \RuntimeException('Storage tidak selamat.');if(!is_dir($d)&&!mkdir($d,0700))throw new \RuntimeException('Storage tidak tersedia.');if(!is_file($d.'/.htaccess')&&file_put_contents($d.'/.htaccess',"Require all denied\n")===false)throw new \RuntimeException('Perlindungan storage gagal.');return $d;}
 public static function stage(\PDO $p,int $u,int $org,array $file):string {Service::permit($p,$u,'templates.manage',$org);if(($file['error']??-1)!==UPLOAD_ERR_OK||!is_uploaded_file($file['tmp_name']??'')||strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION))!=='zip')throw new \InvalidArgumentException('Upload ZIP diperlukan.');$d=self::inspect($file['tmp_name']);$token=bin2hex(random_bytes(24));$dest=self::dir('eforms-packages').'/'.$token.'.zip';if(!move_uploaded_file($file['tmp_name'],$dest))throw new \RuntimeException('Simpanan gagal.');chmod($dest,0600);try{Database::query($p,'INSERT INTO eforms_package_stages(token,actor_id,organisation_id,package_sha256,expires_at) VALUES(?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))',[$token,$u,$org,$d['sha256']]);Audit::record($p,'eforms.package_staged',$u,$org,$token,'eforms',null,null,['sha256'=>$d['sha256']]);return $token;}catch(\Throwable $e){unlink($dest);throw $e;}}
 public static function staged(\PDO $p,int $u,string $token,bool $lock=false):array {if(!preg_match('/\A[a-f0-9]{48}\z/',$token))throw new \RuntimeException('Staging tidak sah.');$s=Database::query($p,'SELECT *,expires_at>UTC_TIMESTAMP() AS fresh FROM eforms_package_stages WHERE token=? AND actor_id=?'.($lock?' FOR UPDATE':''),[$token,$u])->fetch();if(!$s||!$s['fresh'])throw new \RuntimeException('Staging tamat / tidak tersedia.');Service::permit($p,$u,'templates.manage',(int)$s['organisation_id']);$file=self::dir('eforms-packages').'/'.$token.'.zip';$d=self::inspect($file);if(!hash_equals($s['package_sha256'],$d['sha256']))throw new \RuntimeException('Integriti staging gagal.');return ['stage'=>$s,'data'=>$d];}
 public static function conflict(\PDO $p,int $org,array $d):string {$m=$d['manifest'];$f=Database::query($p,'SELECT * FROM eforms_package_forms WHERE organisation_id=? AND form_key=?',[$org,$m['form_id']])->fetch();if(!$f)return $m['revision']===1?'NEW':'BLOCKED: borang baharu mesti revision 1';$old=Database::query($p,'SELECT * FROM eforms_package_imports WHERE package_form_id=? AND package_revision=?',[$f['id'],$m['revision']])->fetch();if($old)return hash_equals($old['package_sha256'],$d['sha256'])?'ALREADY IMPORTED':'BLOCKED: identiti/revision sudah wujud dengan kandungan lain';$max=(int)Database::query($p,'SELECT MAX(package_revision) FROM eforms_package_imports WHERE package_form_id=?',[$f['id']])->fetchColumn();return $m['revision']===$max+1?'NEW REVISION':'BLOCKED: revision tidak berurutan';}
 public static function confirm(\PDO $p,int $u,string $token,array $reviewers):int {$dest=null;try{return Core::tx($p,function()use($p,$u,$token,$reviewers,&$dest){$r=self::staged($p,$u,$token,true);$s=$r['stage'];$d=$r['data'];$org=(int)$s['organisation_id'];if($s['consumed_template_id'])return (int)$s['consumed_template_id'];$m=$d['manifest'];
  Database::query($p,'INSERT INTO eforms_package_forms(organisation_id,form_key) VALUES(?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)',[$org,$m['form_id']]);$f=Database::query($p,'SELECT * FROM eforms_package_forms WHERE organisation_id=? AND form_key=? FOR UPDATE',[$org,$m['form_id']])->fetch();$conflict=self::conflict($p,$org,$d);if(str_starts_with($conflict,'BLOCKED'))throw new \RuntimeException($conflict);if($conflict==='ALREADY IMPORTED')return (int)$f['template_id'];
  if(count($reviewers)!==count($d['steps']))throw new \InvalidArgumentException('Sahkan semua pegawai workflow.');$steps=[];foreach($d['steps'] as $i=>$step){$id=Core::id($reviewers[$i]??null);Service::permit($p,$id,'submissions.review',$org);$steps[]=$step+['user_id'=>$id];}
  $key=bin2hex(random_bytes(24));$dest=self::dir('eforms-originals').'/'.$key.'.pdf';if(file_put_contents($dest,$d['pdf'],LOCK_EX)!==strlen($d['pdf']))throw new \RuntimeException('PDF gagal disimpan.');chmod($dest,0600);
  Database::query($p,'INSERT INTO eforms_pdf_sources(organisation_id,created_by,storage_key,sha256,byte_size,original_name) VALUES(?,?,?,?,?,?)',[$org,$u,$key,hash('sha256',$d['pdf']),strlen($d['pdf']),$m['form_id'].'.pdf']);$source=(int)$p->lastInsertId();$current=$f['template_id']?(int)Database::query($p,'SELECT MAX(id) FROM eforms_versions WHERE template_id=?',[$f['template_id']])->fetchColumn():null;
  $id=Visual::save($p,$u,$org,$m['title'],$d['fields'],$steps,$d['acknowledgement'],$f['template_id']?(int)$f['template_id']:null,$source,$d['definition'],$current);$version=(int)Database::query($p,'SELECT MAX(id) FROM eforms_versions WHERE template_id=?',[$id])->fetchColumn();Database::query($p,'UPDATE eforms_package_forms SET template_id=? WHERE id=?',[$id,$f['id']]);Database::query($p,'INSERT INTO eforms_package_imports(package_form_id,package_revision,version_id,package_sha256,description,imported_by) VALUES(?,?,?,?,?,?)',[$f['id'],$m['revision'],$version,$d['sha256'],$m['description'],$u]);Database::query($p,'UPDATE eforms_package_stages SET consumed_template_id=? WHERE token=?',[$id,$token]);Audit::record($p,'eforms.package_imported',$u,$org,(string)$id,'eforms',null,null,['form_id'=>$m['form_id'],'package_revision'=>$m['revision'],'sha256'=>$d['sha256'],'version_id'=>$version]);return $id;});}catch(\Throwable $e){if($dest&&is_file($dest))unlink($dest);throw $e;}}
}
